    const modRows = await tx`SELECT weapon_id, mod_id FROM weapon_mods WHERE user_id = ${userId}`;
    const weapons = new Set(FREE_WEAPONS);
    const characters = new Set(FREE_CHARACTERS);
    const gadgets = new Set(FREE_GADGETS);
