    for (const r of modRows) {
      if (!isWeaponId(r.weapon_id) || !weapons.has(r.weapon_id) || !isModId(r.mod_id) || !modsFor(WEAPONS[r.weapon_id]).includes(r.mod_id)) continue;
      (mods[r.weapon_id] ??= []).push(r.mod_id);
    }
