      diamonds: wallet.diamonds,
      level: wallet.level,
      weapons: [...weapons],
      characters: CHARACTER_IDS.filter((c) => characters.has(c)),
      gadgets: GADGET_IDS.filter((g) => gadgets.has(g)),
