    ctx.res.writeHead(302, { location: `${home}/${where}`, "set-cookie": `${NONCE_COOKIE}=; Path=/api/auth/oauth; HttpOnly; SameSite=Lax${secure ? "; Secure" : ""}; Max-Age=0`, "cache-control": "no-store" });
